// Configuration
const API_BASE_URL = 'https://api.getrak.com';
const ACCESS_TOKEN = 'YOUR_ACCESS_TOKEN'; // Replace with your actual token

// Function to finish a work order
async function finishWorkOrder(workOrderId, finishData) {
  try {
    const response = await axios.post(
      `${API_BASE_URL}/v1.0/installers/work-orders/${workOrderId}/finish`,
      finishData,
      {
        headers: {
          'Authorization': `Bearer ${ACCESS_TOKEN}`,
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        }
      }
    );

    console.log('Work order finished successfully:', response.data);
    return response.data;
  } catch (error) {
    console.error('Error finishing work order:', error.response?.data || error.message);
    throw error;
  }
}

