const axios = require('axios');

/**
 * Fetch vehicles that haven't been updated recently or have never communicated
 * @param {string} token - Authentication token
 * @param {Object} options - Query parameters
 * @param {string[]} options.include - Relationships to include in response
 * @param {boolean} options.onlyNeverCommunicated - Return only vehicles that never communicated
 * @param {number} options.page - Page number for pagination
 * @returns {Promise<Object>} List of vehicles not updated
 */
async function fetchVehiclesNotUpdated(token, options = {}) {
  const baseURL = 'https://api.getrak.com/v1.0/localization';

  try {
    const params = new URLSearchParams();

    // Add include parameters
    if (options.include && Array.isArray(options.include)) {
      options.include.forEach(item => {
        params.append('include[]', item);
      });
    }

    // Add other parameters
    if (options.onlyNeverCommunicated !== undefined) {
      params.append('only_never_communicated', options.onlyNeverCommunicated);
    }

    if (options.page) {
      params.append('page', options.page);
    }

    const response = await axios.get(`${baseURL}/vehicles-not-updated?${params}`, {
      headers: {
        'Authorization': `Bearer ${token}`,
        'Accept': 'application/json',
        'Content-Type': 'application/json'
      }
    });

    return response.data;
  } catch (error) {
    if (error.response) {
      throw new Error(`API Error: ${error.response.status} - ${error.response.data.message || error.response.statusText}`);
    }
    throw error;
  }
}

// Example usage
async function example() {
  const token = 'your_auth_token_here';

  try {
    // Get all vehicles not updated
    const allVehicles = await fetchVehiclesNotUpdated(token, {
      include: ['client', 'device'],
      page: 1
    });

    console.log('All vehicles not updated:', allVehicles);

    // Get only vehicles that never communicated
    const neverCommunicated = await fetchVehiclesNotUpdated(token, {
      onlyNeverCommunicated: true,
      include: ['client'],
      page: 1
    });

    console.log('Vehicles that never communicated:', neverCommunicated);

  } catch (error) {
    console.error('Error fetching vehicles:', error.message);
  }
}

