async function sendBatchCommand() {
  try {
    const response = await axios.post(
      'https://api.getrak.com/v1.0/commands/templates/commands/batch',
      {
        templateId: 1,
        params: [
          { paramName: 'activated', value: 1 },
          { paramName: 'voltage', value: 5 }
        ],
        vehicles: [
          { vehicleId: 123 },
          { vehicleId: 456 }
        ]
      },
      {
        headers: {
          Authorization: 'Bearer <YOUR_TOKEN>',
          'Content-Type': 'application/json'
        }
      }
    );

    console.log('Total:', response.data.total);
    console.log('Success:', response.data.success);
    console.log('Failed:', response.data.failed);

    response.data.results.forEach(result => {
      if (result.status === 'success') {
        console.log(`Vehicle ${result.vehicleId}: Command ID ${result.commandId || result.requestHistoryId}`);
      } else {
        console.error(`Vehicle ${result.vehicleId}: ${result.error}`);
      }
    });
  } catch (error) {
    console.error('Error:', error.response?.data || error.message);
  }
}

sendBatchCommand();

